const fs=require("fs"),path=require("path"),files=fs.readdirSync(".").filter(e=>e.startsWith("Virtual_Lab V")&&e.endsWith(".html"));0===files.length&&(console.error('❌ Error: No se encontró ningún archivo con el formato "Virtual_Lab VX.html".'),process.exit(1));const inputFile=files[0];console.log(`📄 Procesando archivo original: ${inputFile}`);const htmlContent=fs.readFileSync(inputFile,"utf8"),scriptRegex=/<script>([\s\S]*?)<\/script>\s*<\/body>/i,match=htmlContent.match(scriptRegex);match||(console.error("❌ Error: No se encontró el bloque <script> antes de </body>."),process.exit(1));const jsCode=match[1].trim();fs.writeFileSync("app.js",jsCode,"utf8"),console.log("✅ Archivo app.js generado.");const newHtmlContent=htmlContent.replace(scriptRegex,'<script src="app.min.js"><\/script>\n</body>');fs.writeFileSync("index.html",newHtmlContent,"utf8"),console.log("✅ Archivo index.html generado.");
